-- 094: Paultons Park from RCDB via Carter's screenshots, 2026-10-31. Fills
-- (guarded on no height and no inversions): Cat-O-Pillar, Dino Chase (RCDB has
-- only 0 inversions), Drakon (opened 16 May 2026; its "Euro Fighter" model joins
-- the site's "Gerstlauer Euro-Fighter"), Farmyard Flyer ("Force" -> "Zierer
-- Force", opened 1 Apr 2022). New: Serpent's Curse, MACK Water Coaster opening
-- 2027; Runaway Train (Big Country Motioneering powered, 1992-1999; its later
-- home Dunes Leisure is not a park here). Also Flight of the Pterosaur, Raven
-- ("Bobsled Coaster" -> "Gerstlauer Bobsled"), Storm Chaser ("Spinning Coaster"
-- -> "MACK Spinner"), Velociraptor. NOT touched: the separate "Cobra" row
-- (1610) is Raven's own former name (Cobra 2006-2025) - a duplicate to merge
-- through /edit so riders' logs move with it. Safe to run twice.
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 4, json_object('id', id, 'fields', json_array('h', 's', 'l', 'inv'), 'via', '094') FROM coasters WHERE name = 'Cat-O-Pillar Coaster' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET h = 19.7, s = 19.9, l = 652.9, inv = 0 WHERE name = 'Cat-O-Pillar Coaster' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 1, json_object('id', id, 'fields', json_array('inv'), 'via', '094') FROM coasters WHERE name = 'Dino Chase' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET inv = 0 WHERE name = 'Dino Chase' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 5, json_object('id', id, 'fields', json_array('model', 'h', 'inv', 'opened', 'openedPrec'), 'via', '094') FROM coasters WHERE name = 'Drakon' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET model = 'Gerstlauer Euro-Fighter', h = 75.5, inv = 2, opened = '2026-05-16', openedPrec = 'day' WHERE name = 'Drakon' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 4, json_object('id', id, 'fields', json_array('model', 'inv', 'opened', 'openedPrec'), 'via', '094') FROM coasters WHERE name = 'Farmyard Flyer' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET model = 'Zierer Force', inv = 0, opened = '2022-04-01', openedPrec = 'day' WHERE name = 'Farmyard Flyer' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 7, json_object('id', id, 'fields', json_array('h', 's', 'l', 'inv', 'dur', 'opened', 'openedPrec'), 'via', '094') FROM coasters WHERE name = 'Flight of the Pterosaur' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET h = 65.6, s = 34.2, l = 1295.9, inv = 0, dur = 63, opened = '2016-05-17', openedPrec = 'day' WHERE name = 'Flight of the Pterosaur' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 7, json_object('id', id, 'fields', json_array('model', 'h', 's', 'l', 'inv', 'opened', 'openedPrec'), 'via', '094') FROM coasters WHERE name = 'Raven' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET model = 'Gerstlauer Bobsled', h = 54.2, s = 31.1, l = 1476.4, inv = 0, opened = '2006-03-18', openedPrec = 'day' WHERE name = 'Raven' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 8, json_object('id', id, 'fields', json_array('model', 'h', 's', 'l', 'inv', 'dur', 'opened', 'openedPrec'), 'via', '094') FROM coasters WHERE name = 'Storm Chaser' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET model = 'MACK Spinner', h = 64.0, s = 36.9, l = 1505.9, inv = 0, dur = 116, opened = '2021-04-12', openedPrec = 'day' WHERE name = 'Storm Chaser' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 6, json_object('id', id, 'fields', json_array('h', 's', 'l', 'inv', 'opened', 'openedPrec'), 'via', '094') FROM coasters WHERE name = 'Velociraptor' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
UPDATE coasters SET h = 65.6, s = 36.5, l = 672.6, inv = 0, opened = '2016-05-17', openedPrec = 'day' WHERE name = 'Velociraptor' AND park = 'Paultons Park' AND h IS NULL AND inv IS NULL;
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Runaway Train', 'Paultons Park', 'Steel', 'Big Country Motioneering', NULL, NULL, NULL, NULL, 0, NULL, 1992, '1992', 'year', '1999', 'year', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Runaway Train' AND park = 'Paultons Park');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Runaway Train' AND c.park = 'Paultons Park' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Serpent''s Curse', 'Paultons Park', 'Steel', 'MACK Rides', 'MACK Water Coaster', 75.5, 44.0, 1545.3, 0, NULL, 2027, '2027', 'year', NULL, NULL, 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Serpent''s Curse' AND park = 'Paultons Park');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Serpent''s Curse' AND c.park = 'Paultons Park' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
